CREATE TYPE "FamilyRole" AS ENUM ('parent', 'child');
CREATE TYPE "FamilyAssignmentStatus" AS ENUM ('active', 'completed', 'cancelled');
CREATE TYPE "TaskChangeRequestType" AS ENUM ('update', 'delete');
CREATE TYPE "TaskChangeRequestStatus" AS ENUM ('pending', 'approved', 'rejected');
CREATE TABLE "family_groups" ("id" UUID NOT NULL, "name" VARCHAR(120) NOT NULL, "created_by_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "family_groups_pkey" PRIMARY KEY ("id"));
CREATE TABLE "family_members" ("id" UUID NOT NULL, "family_group_id" UUID NOT NULL, "user_id" UUID NOT NULL, "role" "FamilyRole" NOT NULL, "joined_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "left_at" TIMESTAMP(3), CONSTRAINT "family_members_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "family_members_family_group_id_user_id_key" ON "family_members"("family_group_id", "user_id"); CREATE INDEX "family_members_user_id_left_at_idx" ON "family_members"("user_id", "left_at");
CREATE TABLE "family_invites" ("id" UUID NOT NULL, "family_group_id" UUID NOT NULL, "role" "FamilyRole" NOT NULL, "code_hash" CHAR(64) NOT NULL, "expires_at" TIMESTAMP(3) NOT NULL, "used_by_id" UUID, "used_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "family_invites_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "family_invites_code_hash_key" ON "family_invites"("code_hash"); CREATE INDEX "family_invites_family_group_id_expires_at_idx" ON "family_invites"("family_group_id", "expires_at");
CREATE TABLE "family_task_assignments" ("id" UUID NOT NULL, "family_group_id" UUID NOT NULL, "task_id" UUID NOT NULL, "parent_member_id" UUID NOT NULL, "child_member_id" UUID NOT NULL, "status" "FamilyAssignmentStatus" NOT NULL DEFAULT 'active', "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "family_task_assignments_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "family_task_assignments_task_id_key" ON "family_task_assignments"("task_id"); CREATE INDEX "family_task_assignments_child_member_id_status_idx" ON "family_task_assignments"("child_member_id", "status");
CREATE TABLE "task_change_requests" ("id" UUID NOT NULL, "assignment_id" UUID NOT NULL, "child_member_id" UUID NOT NULL, "request_type" "TaskChangeRequestType" NOT NULL, "reason" TEXT NOT NULL, "proposed_patch" JSONB, "status" "TaskChangeRequestStatus" NOT NULL DEFAULT 'pending', "reviewed_by_user_id" UUID, "reviewed_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "task_change_requests_pkey" PRIMARY KEY ("id"));
CREATE INDEX "task_change_requests_assignment_id_status_idx" ON "task_change_requests"("assignment_id", "status");
ALTER TABLE "family_groups" ADD CONSTRAINT "family_groups_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "family_members" ADD CONSTRAINT "family_members_family_group_id_fkey" FOREIGN KEY ("family_group_id") REFERENCES "family_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "family_members" ADD CONSTRAINT "family_members_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "family_invites" ADD CONSTRAINT "family_invites_family_group_id_fkey" FOREIGN KEY ("family_group_id") REFERENCES "family_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "family_invites" ADD CONSTRAINT "family_invites_used_by_id_fkey" FOREIGN KEY ("used_by_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "family_task_assignments" ADD CONSTRAINT "family_task_assignments_family_group_id_fkey" FOREIGN KEY ("family_group_id") REFERENCES "family_groups"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "family_task_assignments" ADD CONSTRAINT "family_task_assignments_task_id_fkey" FOREIGN KEY ("task_id") REFERENCES "tasks"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "family_task_assignments" ADD CONSTRAINT "family_task_assignments_parent_member_id_fkey" FOREIGN KEY ("parent_member_id") REFERENCES "family_members"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "family_task_assignments" ADD CONSTRAINT "family_task_assignments_child_member_id_fkey" FOREIGN KEY ("child_member_id") REFERENCES "family_members"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "task_change_requests" ADD CONSTRAINT "task_change_requests_assignment_id_fkey" FOREIGN KEY ("assignment_id") REFERENCES "family_task_assignments"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "task_change_requests" ADD CONSTRAINT "task_change_requests_child_member_id_fkey" FOREIGN KEY ("child_member_id") REFERENCES "family_members"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "task_change_requests" ADD CONSTRAINT "task_change_requests_reviewed_by_user_id_fkey" FOREIGN KEY ("reviewed_by_user_id") REFERENCES "users"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "tasks" ADD CONSTRAINT "tasks_created_by_family_member_id_fkey" FOREIGN KEY ("created_by_family_member_id") REFERENCES "family_members"("id") ON DELETE SET NULL ON UPDATE CASCADE;
